// T7 probes against the running dev server. Usage: node probe.mjs <step> [billId] [amount]
import { readFileSync } from 'node:fs'
import { createHmac, randomUUID } from 'node:crypto'

const env = Object.fromEntries(
  readFileSync('/home/electronica-care/ezy-prep/exam/app/.env.local', 'utf8')
    .split('\n')
    .filter((l) => /^[A-Z_]+=/.test(l))
    .map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1).trim()]),
)
const BASE = 'http://127.0.0.1:3000'
const SUPA = 'http://127.0.0.1:54321'
const KEY = env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY

async function token(email) {
  const r = await fetch(`${SUPA}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { apikey: KEY, 'content-type': 'application/json' },
    body: JSON.stringify({ email, password: 'RentDemo#2026' }),
  })
  const j = await r.json()
  if (!j.access_token) throw new Error(`sign in failed for ${email}: ${r.status}`)
  return j.access_token
}

async function aisyahLease(t) {
  const r = await fetch(`${SUPA}/rest/v1/leases?select=id`, { headers: { apikey: KEY, authorization: `Bearer ${t}` } })
  const rows = await r.json()
  return rows[0].id
}

async function call(method, path, t, body) {
  const headers = {}
  if (t) headers.authorization = `Bearer ${t}`
  if (body !== undefined) headers['content-type'] = 'application/json'
  const r = await fetch(`${BASE}${path}`, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) })
  const text = await r.text()
  return `${r.status} ${text}`
}

function signed(fields, key = 'test_x_signature_key') {
  const source = Object.keys(fields).sort().map((k) => `${k}${fields[k]}`).join('|')
  return { ...fields, x_signature: createHmac('sha256', key).update(source).digest('hex') }
}

async function hook(fields) {
  const r = await fetch(`${BASE}/api/webhooks/gateway`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
  })
  return `${r.status} ${await r.text()}`
}

const step = process.argv[2]
const aisyah = await token('aisyah@northwind.test')
const lease = await aisyahLease(aisyah)

if (step === 'create') {
  console.log('lease', lease)
  console.log('GET lease (before)', await call('GET', `/api/leases/${lease}`, aisyah))
  console.log('no auth POST gateway-bills', await call('POST', `/api/leases/${lease}/gateway-bills`))
  console.log('aisyah POST gateway-bills', await call('POST', `/api/leases/${lease}/gateway-bills`, aisyah))
} else if (step === 'check') {
  const billId = process.argv[3]
  const amount = process.argv[4]
  const staff = await token('staff@northwind.test')
  const ben = await token('ben@northwind.test')
  const chen = await token('chen@beta.test')
  console.log('GET lease (after)', await call('GET', `/api/leases/${lease}`, aisyah))
  console.log('GET bill as aisyah', await call('GET', `/api/gateway-bills/${billId}`, aisyah))
  console.log('GET bill as staff', await call('GET', `/api/gateway-bills/${billId}`, staff))
  console.log('GET bill as ben', await call('GET', `/api/gateway-bills/${billId}`, ben))
  console.log('GET bill as chen', await call('GET', `/api/gateway-bills/${billId}`, chen))
  console.log('GET bill malformed', await call('GET', `/api/gateway-bills/not-a-uuid`, aisyah))
  console.log('GET bill no auth', await call('GET', `/api/gateway-bills/${billId}`))
  const paidAt = '2026-10-26 10:00:00 +0800'
  const base = { id: billId, paid: 'true', paid_amount: amount, paid_at: paidAt, transaction_id: 'TX-probe', transaction_status: 'completed' }
  const forged = signed(base, 'wrong_key')
  console.log('(b) forged signature', await hook(forged))
  console.log('(b) missing signature', await hook(base))
  const tampered = { ...signed(base), paid_amount: '1' }
  console.log('(b) tampered field', await hook(tampered))
  console.log('(b) duplicate key', await fetch(`${BASE}/api/webhooks/gateway`, {
    method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(signed(base)).toString() + '&paid=false',
  }).then(async (r) => `${r.status} ${await r.text()}`))
  console.log('(c) unknown uuid bill', await hook(signed({ ...base, id: randomUUID() })))
  console.log('(c) non-uuid bill', await hook(signed({ ...base, id: 'bill_8f3a2c' })))
  console.log('(d) wrong amount', await hook(signed({ ...base, paid_amount: String(Number(amount) + 1) })))
  console.log('extra field, paid=true repeat', await hook(signed({ ...base, extra_field: 'x' })))
  console.log('paid=false on paid bill', await hook(signed({ ...base, paid: 'false', paid_amount: '0', transaction_status: 'failed' })))
  console.log('bad paid flag', await hook(signed({ ...base, paid: 'yes' })))
  console.log('bad paid_at', await hook(signed({ ...base, paid_at: '2026-02-30 10:00:00 +0800' })))
  console.log('(e) staff POST gateway-bills', await call('POST', `/api/leases/${lease}/gateway-bills`, staff))
  console.log('(e) ben POST gateway-bills', await call('POST', `/api/leases/${lease}/gateway-bills`, ben))
  console.log('(e) chen POST gateway-bills', await call('POST', `/api/leases/${lease}/gateway-bills`, chen))
  console.log('aisyah POST gateway-bills now (expect 422)', await call('POST', `/api/leases/${lease}/gateway-bills`, aisyah))
  console.log('aisyah POST malformed lease id', await call('POST', `/api/leases/nope/gateway-bills`, aisyah))
}

